function [a] = fsw_default_allocation(can)
%FSW_DEFAULT_ALLOCATION  The allocation a product flies when neither it nor the scenario names one: the first it can fly of the CMG's, the
%   VSCMG's, the IDMAS split and the rotors' pseudo-inverse, else none.
%   can: int[4] (passed a whole number)
%   returns a: AllocAlg (passed a choice, as its option's number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = 0;
    a = 4;
    if (can(3) == 1)
        a = 2;
    elseif (can(4) == 1)
        a = 3;
    elseif (can(2) == 1)
        a = 1;
    elseif (can(1) == 1)
        a = 0;
    end
end
